total_rating_count = 32000000
default_offset = 2000000 # 5000000
total_user_count = 330975
gene_count = 1128


def get_rating_samples(count: int | None = None, offset: int = 0, file: str = aggregation_path + "ratings.csv"):
	"""Gets samples from a movie rating dataset. If count is left unset, it reads all ratings.
	Always set file if importing this function (since the relative path breaks if this function is called from elsewhere)."""
	return np.loadtxt(file,
	                  delimiter=',', max_rows=count, skiprows=1 + offset) # dtype="int,int,float,int" - saved memory, prevented it from being a 2d array


