def get_movie_genres(file: str = aggregation_path + "genre-vectors-split.csv"):
	movie_genre_data = np.loadtxt(file,
	                              delimiter=',', skiprows=1)
	movie_genre_ids = np.loadtxt('/'.join(file.split('/')[:-1]) + "/genre-movies.csv",
	                             delimiter=',', skiprows=1)
	return {movie_id: movie_genre_data[i] for i, movie_id in enumerate(movie_genre_ids)}


def get_movie_genome_scores_raw(file: str = aggregation_path + "genome-scores.csv"):
 	movie_genome_data = np.loadtxt(file,
 	                               delimiter=',', skiprows=1)
 	movie_count = len(movie_genome_data) // gene_count
 	return {movie_genome_data[i * gene_count][0]: movie_genome_data[i * gene_count:(i + 1) * gene_count, 2] for i in range(movie_count)}


