def get_movie_genome_scores(file: str = aggregation_path + "genome-vectors-split.csv"):
	# From split aggregated vectors
	movies_genome_data = np.loadtxt(file,
	                               delimiter=',')
	movie_ids = np.loadtxt('/'.join(file.split('/')[:-1]) + "/genome-movies.csv",
	                              delimiter=',', skiprows=1)
	return {movie_id: movie_genome_data for movie_id, movie_genome_data in zip(movie_ids, movies_genome_data)}


def get_scores(file: str):
	return np.loadtxt(file, skiprows=1)


def get_matrix(file: str):
	return np.loadtxt(file, delimiter=',')


def save_ratings(out_name, ratings):
	np.savetxt(out_name, ratings,
	           fmt='%d,%d,%.1f,%d', comments="", header="userId,movieId,rating,timestamp")


def save_scores(out_name, scores):
	np.savetxt(out_name, scores,
	           fmt='%.10f', comments="", header="score")


def save_matrix(out_name, matrix):
	width = len(matrix[0])
	np.savetxt(out_name, matrix,
	           fmt='%.10f'+',%.10f'*(width-1), comments="")


def select_ratings(rating_count: int, ratings):
	"""Selects a random sample of ratings."""
	ratings_filter = np.random.choice(np.arange(len(ratings)), size=min(len(ratings), rating_count), replace=False)
	return ratings[ratings_filter]


def select_ratings_user(user_count: int, ratings):
	"""Selects ratings grouped by random users. Each movie has an average of 100 ratings."""
	last_user = ratings[-1][0]
	users = np.random.choice(np.arange(1, last_user), size=min(last_user, user_count), replace=False) # omits last user (as data may be cut off)
	users_filter = np.isin(ratings[:, 0], users)
	ratings_filtered = ratings[users_filter] # [ratings[i] for i in range(len(ratings)) if ratings[i][0] in users]
	return ratings_filtered


def select_ratings_movie(movie_count: int, ratings):
	"""Selects ratings grouped by random movies. Each movie has an average of 400 ratings, though with a smaller rating set that value is smaller.
	Note that this function does not return all ratings for a movie, but all ratings found within the first sample_count samples.
	Note the bias towards more popular movies."""
	all_movies = np.unique(ratings[:, 1])
	# all_movies = np.unique([rating[1] for rating in ratings])
	movies = np.random.choice(all_movies, size=min(len(all_movies), movie_count), replace=False)
	movies_filter = np.isin(ratings[:, 1], movies)
	ratings_filtered = ratings[movies_filter] # [ratings[i] for i in range(len(ratings)) if ratings[i][1] in movies]
	return ratings_filtered


