def generate_aggregations() -> None:
	print("Getting genome scores...")
	genome_scores = get_movie_genome_scores_raw()

	print("Saving aggregate data...")
	np.savetxt(aggregation_path + "genome-vectors.csv", [[str(int(k)) + ',' + '|'.join(v.astype(str))] for k, v in genome_scores.items()],
	           fmt='%s', comments="", header="movieId,relevanceVector")
	save_matrix(aggregation_path + "genome-vectors-split.csv", list(genome_scores.values()))


if __name__ == "__main__":
	# generate_aggregations()
	main()
